import { Component, OnInit, CUSTOM_ELEMENTS_SCHEMA } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormArray, FormBuilder, FormControl, FormGroup, FormsModule, ReactiveFormsModule, Validators } from '@angular/forms';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { PostEditor } from '../post-editor';
import { DropdownManagerService } from 'src/app/dropdown-manager/dropdown-manager.service';
import { take } from 'rxjs';
import { environment } from 'src/environments/environment';
import { MediaService } from 'src/app/core/media.service';
import { optimizeImageForUpload } from 'src/app/core/utils/image-optimizer.util';
import { NotificationService } from 'src/app/core/services/notification.service';


@Component({
  selector: 'app-post-editor',
  templateUrl: './post-editor.component.html',
  styleUrls: ['./post-editor.component.scss'],
  standalone: true,
  imports: [CommonModule, FormsModule, ReactiveFormsModule, RouterLink],
  schemas: [CUSTOM_ELEMENTS_SCHEMA],
})
export class PostEditorComponent implements OnInit {
  postId: string | null = null;
  isEditMode: boolean = false;
  postForm!: FormGroup;

  // Image handling
  selectedFile: File | null = null;
  imagePreview: string | null = null;
  readonly imageBaseUrl = (environment.mediaBaseUrl || '').replace(/\/?$/, '/');
  existingImageUrl: string | null = null;

  categories: string[] = [];
  isContentPreview: boolean = false;
  isLoading = false;

  constructor(
    private fb: FormBuilder,
    private route: ActivatedRoute,
    private router: Router,
    private postEditorService: PostEditor,
    private dropdownService: DropdownManagerService,
    private notify: NotificationService
    , private media: MediaService
  ) { }

  toggleContentPreview() {
    this.isContentPreview = !this.isContentPreview;
  }

  insertFormat(prefix: string, suffix: string = '') {
    const current = this.postForm.get('content')?.value || '';
    const updated = current ? `${current}\n${prefix}sample text${suffix}` : `${prefix}sample text${suffix}`;
    this.postForm.patchValue({ content: updated });
  }

  ngOnInit() {
    this.initForm();
    this.loadManagedCategories();

    this.route.params.subscribe(params => {
      if (params['id']) {
        this.postId = String(params['id']);
        this.isEditMode = true;
        this.loadPost(this.postId);
      }
    });
  }

  private loadManagedCategories() {
    this.dropdownService.getGroupOptions('blogCategory').pipe(take(1)).subscribe((options) => {
      if (options.length > 0) {
        this.categories = options.map((o) => o.label);
      }
    });
  }

  initForm() {
    this.postForm = this.fb.group({
      title: ['', Validators.required],
      excerpt: ['', Validators.required],
      content: ['', Validators.required],
      category: ['', Validators.required],
      tags: this.fb.array([this.createTagControl()]),
      status: ['pending'],
      publishDate: [new Date().toISOString(), Validators.required],
      author: ['Admin', Validators.required]
    });
  }

  get tags(): FormArray {
    return this.postForm.get('tags') as FormArray;
  }

  createTagControl(value: string = ''): FormControl {
    return this.fb.control(value);
  }

  addTag() {
    this.tags.push(this.createTagControl());
  }

  removeTag(index: number) {
    if (this.tags.length > 1) {
      this.tags.removeAt(index);
    }
  }

  loadPost(id: string) {
    this.postEditorService.getPost(id).subscribe({
      next: (post: any) => {
        // Clear existing tags
        while (this.tags.length) {
          this.tags.removeAt(0);
        }

        // Add tags from loaded post
        if (post.tags && post.tags.length > 0) {
          post.tags.forEach((tag: string) => {
            this.tags.push(this.createTagControl(tag));
          });
        } else {
          this.tags.push(this.createTagControl());
        }

        // Set existing image
        if (post.featured_image) {
          this.existingImageUrl = post.featured_image;
          this.imagePreview = post.featured_image;
        }

        // Patch form with post data
        this.postForm.patchValue({
          title: post.title,
          excerpt: post.excerpt,
          content: post.content,
          category: post.category,
          status: post.status,
          publishDate: post.published_at || new Date().toISOString(),
          author: post.author_id || 'Admin'
        });
      },
      error: (err) => {
        this.showToast('Failed to load post', 'danger');
      }
    });
  }

  loadCategories() {
    this.postEditorService.getCategories().subscribe({
      next: (cats) => {
        this.categories = cats.map(c => c.name);
      },
      error: (err) => {
      }
    });
  }

  async onImageSelect(event: any) {
    const file = event.target.files[0];
    if (file) {
      if (!this.isAcceptedImage(file)) {
        this.showToast('Please select an image file', 'warning');
        return;
      }

      const maxSize = 25 * 1024 * 1024; // 25MB raw limit
      if (file.size > maxSize) {
        this.showToast('Image size should be less than 25MB', 'warning');
        return;
      }

      const optimized = await optimizeImageForUpload(file);
      this.selectedFile = optimized;

      const reader = new FileReader();
      reader.onload = (e: any) => {
        this.imagePreview = e.target.result;
      };
      reader.readAsDataURL(optimized);

      this.showToast('HD Image optimized and selected', 'success');
    }
  }

  private isAcceptedImage(file: File): boolean {
    const mime = String(file?.type || '').toLowerCase();
    if (mime.startsWith('image/')) return true;

    const name = String(file?.name || '').toLowerCase();
    const ext = name.includes('.') ? name.split('.').pop() || '' : '';
    const imageExt = new Set([
      'jpg', 'jpeg', 'png', 'gif', 'webp', 'avif', 'bmp', 'svg',
      'tif', 'tiff', 'ico', 'heic', 'heif', 'jfif'
    ]);
    return imageExt.has(ext);
  }

  removeImage() {
    this.selectedFile = null;
    this.imagePreview = null;
    this.existingImageUrl = null;

    // Clear file input
    const fileInput = document.querySelector('input[type="file"]') as HTMLInputElement;
    if (fileInput) {
      fileInput.value = '';
    }

    this.showToast('Image removed', 'success');
  }

  getImageSrc(src: string | null): string {
    if (!src) return '';
    return this.media.resolve(src);
  }

  async publish() {
    if (this.postForm.invalid) {
      Object.keys(this.postForm.controls).forEach(key => {
        this.postForm.get(key)?.markAsTouched();
      });
      this.showToast('Please fill all required fields', 'warning');
      return;
    }

    this.postForm.patchValue({ status: 'published' });
    await this.savePost();
  }

  async savePost() {
    this.isLoading = true;

    const formValue = { ...this.postForm.value };

    // Filter out empty tags
    formValue.tags = formValue.tags.filter((tag: string) => tag && tag.trim() !== '');

    // Create FormData
    const formData = new FormData();

    // Append all form fields
    formData.append('title', formValue.title);
    formData.append('excerpt', formValue.excerpt);
    formData.append('content', formValue.content);
    formData.append('category', formValue.category);
    formData.append('status', formValue.status);
    formData.append('publishDate', formValue.publishDate);
    formData.append('author', formValue.author);
    formData.append('tags', JSON.stringify(formValue.tags));

    // Append image file if selected (new upload)
    if (this.selectedFile) {
      formData.append('image', this.selectedFile, this.selectedFile.name);
    } else if (this.existingImageUrl && this.imagePreview) {
      // Keep existing image URL if not changed
      formData.append('existingImageUrl', this.existingImageUrl);
    }

    // Save post
    this.postEditorService.savePost(this.postId, formData).subscribe({
      next: (res: any) => {
        this.isLoading = false;
        this.showToast('Post saved successfully!', 'success');
        this.router.navigate(['/admin/blog/posts']);
      },
      error: (err: any) => {
        this.isLoading = false;
        this.showToast('Failed to save post', 'danger');
      }
    });
  }

  async showToast(message: string, color: 'success' | 'danger' | 'warning' = 'success') {
    const toast = this.notify.show('Operation completed.');
  }
}
